<?php
if(PHP_SAPI!=='cli'){http_response_code(403);exit("CLI only\n");}require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/config/database.php';
function cron_dump(PDO $pdo): string {$out="-- Barangay Information System automatic backup\n-- Generated: ".date('c')."\nSET FOREIGN_KEY_CHECKS=0;\n\n";foreach($pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $table){$create=$pdo->query('SHOW CREATE TABLE `'.str_replace('`','``',$table).'`')->fetch();$out.=$create['Create Table'].";\n\n";foreach($pdo->query('SELECT * FROM `'.str_replace('`','``',$table).'`')->fetchAll() as $row){$cols=array_map(fn($c)=>'`'.$c.'`',array_keys($row));$vals=array_map(fn($v)=>$v===null?'NULL':$pdo->quote((string)$v),array_values($row));$out.="INSERT INTO `{$table}` (".implode(',',$cols).") VALUES (".implode(',',$vals).");\n";}$out.="\n";}return $out."SET FOREIGN_KEY_CHECKS=1;\n";}
$dir=__DIR__.'/../backups';if(!is_dir($dir))mkdir($dir,0750,true);$dump=cron_dump(db());$key=getenv('BACKUP_ENCRYPTION_KEY')?:'';$filename='barangay-auto-'.date('Y-m-d-His').($key?'.sql.enc':'.sql');$payload=$dump;if($key){$iv=random_bytes(16);$payload="BIS-AES256\n".base64_encode($iv)."\n".base64_encode(openssl_encrypt($dump,'aes-256-cbc',hash('sha256',$key,true),OPENSSL_RAW_DATA,$iv));}file_put_contents($dir.'/'.$filename,$payload,LOCK_EX);echo "Created {$filename} (".strlen($payload)." bytes)\n";
